  "findings": [
    {
      "benefit": "Death",
      "years": [
        2016,
        2017
      ],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "A/E rises abruptly to ~1.25 in 2016 and ~1.24 in 2017, about +24% versus expected, then reverts to 0.90-0.96 in 2018-2020 and roughly 0.92-1.03 from 2021 onward",
      "confidence": 0.75,
      "evidence": [
        "ae_death_by_year.csv: 2016 AE=1.250 (Actual 362 vs Expected 290) and 2017 AE=1.239 (Actual 418 vs Expected 337), versus adjacent years 2015=1.035 and 2018=0.898",
        "Death 2015-2024 empirical A/E standard deviation is ~0.125, well above the Poisson scale of ~1/sqrt(E) ≈ 0.03-0.06, so this is not being flagged using Poisson z-scores",
        "Later Death A/E values are closer to baseline: 2021=1.032, 2022=0.963, 2023=1.027, 2024=0.915"
      ],
      "recommended_action": "Investigate the 2016-2017 death claim elevation, focusing on large or late-reported claims, cause-of-death mix, data entry issues, exposure/billing changes, underwriting selection, and any mortality assumption changes; assess credibility and valuation/pricing impact for that window. CI, TPD, IP claim experience and IP termination rates by diagnosis appear broadly consistent with noise and do not require separate action."
    }
  ]
}

